require 'open3'

# A pull-request workflow on ordinary issues: an issue of the "Pull request"
# tracker names a branch (and a target branch, default main); this lists the
# branch's commits on the issue, with a link to the diff, and closes it as
# merged once the branch has been merged into the target in git. See README.

# The version is the release tag: in a release archive git archive has put
# it into VERSION (export-subst in .gitattributes); in a clone, git
# describe gives it (plus commits since, if any).
plugin_version = File.read(File.join(__dir__, 'VERSION')).strip
if plugin_version.start_with?('$Format')
  plugin_version = 'unknown'
  if File.exist?(File.join(__dir__, '.git'))
    out, status = Open3.capture2('git', '-C', __dir__, 'describe', '--tags', '--always',
                                 err: File::NULL)
    plugin_version = out.strip if status.success?
  end
end

Redmine::Plugin.register :git_pull_requests do
  name 'Pull requests'
  author "Colin 't Hart (code generated by Claude)"
  description 'Issues of a "Pull request" tracker list their branch\'s commits, ' \
              'and are closed when the branch is merged.'
  version plugin_version
  url 'https://github.com/cthart/git_pull_requests'
  requires_redmine version_or_higher: '7.0.0'
end

# init.rb runs again at each code reload in development: prepend only once
unless Repository::Git <= GitPullRequests::RepositoryGitPatch
  Repository::Git.prepend GitPullRequests::RepositoryGitPatch
end
# Loading the class registers the view hook (Redmine::Hook::Listener.inherited)
GitPullRequests::Hooks.instance
